(() => {
  'use strict';
  const $=id=>document.getElementById(id);
  const iconPaths={book:'M4 4h6a3 3 0 0 1 2 2v14a4 4 0 0 0-4-2H4z M20 4h-6a3 3 0 0 0-2 2v14a4 4 0 0 1 4-2h4z',lock:'M6 10h12v10H6z M8 10V7a4 4 0 0 1 8 0v3',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z m-4 9 3 3 5-6',flask:'M9 3h6 M10 3v6L5 18a2 2 0 0 0 2 3h10a2 2 0 0 0 2-3l-5-9V3 M8 14h8',leaf:'M20 4C9 2 3 8 6 16c7 4 14-1 14-12Z M5 21 16 9 M9 16v-5 M13 12h4',math:'M5 4h14v16H5z M8 8h8 M8 12h2 M14 12h2 M8 16h2 M14 16h2',atom:'M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M3 8c2-4 20 5 18 9S1 12 3 8 M3 17C1 13 19 4 21 8S5 21 3 17 M12 2c5 0 5 20 0 20S7 2 12 2',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 m-5 5 5-5 5 5 M4 16v5h16v-5',plus:'M12 5v14 M5 12h14',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15 M16 16l5 5',rotate:'M4 10a8 8 0 1 1 1 8 M4 4v6h6',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 11v6 M12 7v1',layout:'M3 4h18v16H3z M12 4v16 M6 8h3 M6 11h3 M15 8h3 M15 11h3',printer:'M6 9V3h12v6 M6 17H3v-8h18v8h-3 M6 14h12v7H6z M17 11h1',check:'m5 12 4 4L19 6','arrow-left':'m12 5-7 7 7 7 M5 12h15','chevron-left':'m15 5-7 7 7 7','chevron-right':'m9 5 7 7-7 7',edit:'m15 4 5 5 M4 20l5-1L21 7l-5-5L4 14z',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',file:'M6 3h8l5 5v13H6z M14 3v6h5 M9 13h7 M9 16h7',warning:'m12 3 10 18H2z M12 9v5 M12 17v1'};
  const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" stroke-linecap="round" stroke-linejoin="round"><path d="${iconPaths[name]||iconPaths.book}"/></svg>`;
  function icons(){document.querySelectorAll('[data-icon]').forEach(e=>e.outerHTML=icon(e.dataset.icon));}
  const subjects=[{id:'chemistry',name:'化学',en:'CHEMISTRY',icon:'flask',color:'#718b69',bg:'#eef4e9',topics:['化学基本概念','离子反应方程式','氧化还原反应','钠','铁','镁、铝、铜','氯','硫','氧','氮与氨','实验题']},{id:'biology',name:'生物',en:'BIOLOGY',icon:'leaf',color:'#b49b60',bg:'#f8f3e6',topics:['细胞的结构与功能','物质运输','酶与ATP','光合作用与呼吸作用','遗传与进化','稳态与调节']},{id:'math',name:'数学',en:'MATHEMATICS',icon:'math',color:'#8b8eaa',bg:'#f0eff7',topics:['函数与导数','数列','立体几何','解析几何','概率与统计','三角函数']},{id:'physics',name:'物理',en:'PHYSICS',icon:'atom',color:'#b78a74',bg:'#f8f0ea',topics:['圆周运动','动能与机械能','直线运动','牛顿运动定律','万有引力','电场与磁场']}];
  const subject=id=>subjects.find(s=>s.id===id)||subjects[0];
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const id=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
  const today=()=>new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  const DRAFT='zhixu.local.draft.v2';
  let state={version:2,questions:[],settings:NoteSchema.settings()},revision='',ready=false,saving=false,polling=false,editingRevision='';
  let selectedSubject='',query='',topicFilters=new Set(),topicsExpanded=false,statusFilter='',dateFrom='',dateTo='',todayMode=false,selectedIds=new Set(),currentPage=1,editing=false,editingId=null,previewTimer,toastTimer;
  const validQuestion=q=>NoteSchema.errors(q).length===0;
  function formulaProblems(q){return ['question','answer','explanation','notes','equation'].flatMap(k=>Formula.check(q[k]||'',{equation:k==='equation'}).map(error=>({field:k,error})));}
  async function loadLocal(manual=false){if(polling||saving)return;polling=true;const requestRevision=revision;try{const res=await fetch('/api/library',{cache:'no-store'});const data=await res.json();if(!res.ok)throw Error(data.error||'无法读取本地题库');if(revision!==requestRevision)return;const changed=revision!==data.revision;state={version:2,questions:data.questions,settings:data.settings};revision=data.revision;ready=true;$('sync-error').hidden=false;$('sync-error').textContent=data.formulaIssues?.length?'有 '+data.formulaIssues.length+' 处公式语法待修正。请编辑标红的公式。':'';$('sync-error').hidden=!data.formulaIssues?.length;$('local-status').textContent='已连接本地文件 · 自动同步中';if(changed){syncSettings();renderAll();}if(manual)toast('本地文件已同步'+(editing?'；当前草稿已保留。':'。'));}catch(e){$('local-status').textContent='本地文件连接异常';$('sync-error').hidden=false;$('sync-error').textContent=e.message+'。请保留本地服务窗口并检查 data/questions.json。';if(manual)toast(e.message);}finally{polling=false;}}
  async function commit(next,expectedRevision=revision){if(!ready||saving){toast('请等待本地题库连接或当前保存完成。');return false;}saving=true;try{const res=await fetch('/api/library',{method:'PUT',headers:{'Content-Type':'application/json','X-Zhixu-Local':'1','If-Match':expectedRevision},body:JSON.stringify({version:2,questions:next.questions,settings:next.settings})});const data=await res.json();if(!res.ok)throw Error(data.error+(res.status===409&&editing?' 请保留草稿内容，取消编辑并重新打开后再保存。':''));state={version:2,questions:data.questions,settings:data.settings};revision=data.revision;$('local-status').textContent='已保存到 data/questions.json';return true;}catch(e){toast(e.message);$('form-message').textContent=e.message;return false;}finally{saving=false;}}
  function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4200);}
  const style=s=>`--subject-color:${s.color};--subject-bg:${s.bg}`;
  function localDate(value){const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
  function filtered(){return state.questions.filter(q=>(!selectedSubject||q.subject===selectedSubject)&&(!topicFilters.size||topicFilters.has(q.topic))&&(!statusFilter||(statusFilter==='mastered'?q.mastered:!q.mastered))&&(!dateFrom||localDate(q.createdAt)>=dateFrom)&&(!dateTo||localDate(q.createdAt)<=dateTo)&&(!query||[q.question,q.answer,q.explanation,q.notes,q.topic,q.equation].some(x=>(x||'').toLowerCase().includes(query.toLowerCase())))).sort((a,b)=>{const t=Date.parse(b.createdAt)-Date.parse(a.createdAt);return Number.isFinite(t)?t:0;});}
  function selectedQuestions(){return state.questions.filter(q=>selectedIds.has(q.id)).sort((a,b)=>{const t=Date.parse(b.createdAt)-Date.parse(a.createdAt);return Number.isFinite(t)?t:0;});}
  function renderSelection(){const visible=filtered().filter(q=>selectedIds.has(q.id)).length;const hidden=selectedIds.size-visible;$('selection-summary').textContent=`已选 ${selectedIds.size} 道${hidden?` · ${hidden} 道被当前筛选隐藏`:''}`;$('clear-selection').disabled=!selectedIds.size;$('select-visible').disabled=!filtered().length;}
  const imageUrl=(q,im)=>`/assets/${encodeURIComponent(q.id)}/${encodeURIComponent(im.file)}`;
  function richQuestion(q){const source=q.question||'',used=new Set();let html=source.split(/(\[\[image:[a-zA-Z0-9_-]+\.(?:png|jpe?g|webp)\]\])/i).map(part=>{const match=part.match(/^\[\[image:([^\]]+)\]\]$/);if(!match)return Formula.render(part);const image=(q.images||[]).find(x=>x.file===match[1]);if(!image)return esc(part);used.add(image.file);const src=imageUrl(q,image);return `<span class="question-inline-image"><button type="button" class="image-thumb" data-image="${esc(src)}" data-alt="${esc(image.alt)}"><img src="${esc(src)}" alt="${esc(image.alt)}" loading="lazy"><small>${esc(image.alt)}</small></button></span>`;}).join('');const fallback=(q.images||[]).filter(image=>!used.has(image.file)&&!['answer','explanation','notes'].some(k=>(q[k]||'').includes(`[[image:${image.file}]]`)));return html+fallback.map(image=>{const src=imageUrl(q,image);return `<span class="question-inline-image"><button type="button" class="image-thumb" data-image="${esc(src)}" data-alt="${esc(image.alt)}"><img src="${esc(src)}" alt="${esc(image.alt)}" loading="lazy"><small>${esc(image.alt)}</small></button></span>`;}).join('');}
  function renderNav(){document.body.classList.toggle('subject-selected',!!selectedSubject);document.body.classList.toggle('overview-mode',!selectedSubject);$('page-title').textContent=selectedSubject?subject(selectedSubject).name+'错题':'错题本';$('page-title-icon').innerHTML=selectedSubject?icon(subject(selectedSubject).icon):'';const counts=s=>state.questions.filter(q=>!s||q.subject===s).length;$('subject-nav').innerHTML=`<button class="nav-item ${selectedSubject?'':'active'}" data-subject=""><span>${icon('book')}全部错题</span><small>${counts('')}</small></button>`+subjects.map(s=>`<button class="nav-item ${selectedSubject===s.id?'active':''}" data-subject="${s.id}"><span>${icon(s.icon)}${s.name}</span><small>${counts(s.id)}</small></button>`).join('');}
  function renderTopics(){const topics=[...new Set(state.questions.filter(q=>!selectedSubject||q.subject===selectedSubject).map(q=>q.topic))].sort((a,b)=>a.localeCompare(b,'zh-CN'));topicFilters=new Set([...topicFilters].filter(t=>topics.includes(t)));const options=$('topic-options-filter');options.classList.remove('expanded');options.innerHTML=topics.length?topics.map(t=>`<label class="topic-option"><input type="checkbox" value="${esc(t)}" ${topicFilters.has(t)?'checked':''}><span>${esc(t)}</span></label>`).join(''):'<span class="no-topics">暂无题目类别</span>';const hasMore=options.scrollHeight>options.clientHeight+1;options.classList.toggle('expanded',topicsExpanded);const toggle=$('topic-expand');toggle.hidden=!hasMore;toggle.textContent=topicsExpanded?'收起类别':'展开全部类别';toggle.setAttribute('aria-expanded',String(topicsExpanded));$('topic-summary').textContent=topicFilters.size?`已选 ${topicFilters.size} 类`:'全部类别';}
  function renderList(){const items=filtered();const pageSize=10;const pageCount=Math.max(1,Math.ceil(items.length/pageSize));currentPage=Math.min(currentPage,pageCount);const pageItems=items.slice((currentPage-1)*pageSize,currentPage*pageSize);$('collection-title').textContent=selectedSubject?'题目筛选':'题库概况';$('collection-count').textContent=selectedSubject?items.length+' 道':'';$('overview').hidden=!!selectedSubject;const topicCounts=new Map();for(const q of state.questions){const key=q.subject+'|'+q.topic;const item=topicCounts.get(key)||{subject:q.subject,topic:q.topic,count:0};item.count++;topicCounts.set(key,item);}const topics=[...topicCounts.values()].sort((a,b)=>b.count-a.count||a.topic.localeCompare(b.topic,'zh-CN')).slice(0,8);const maxTopic=topics[0]?.count||1;$('overview').innerHTML=`<div class="overview-total"><strong>${state.questions.length}</strong><span>道错题已收录</span></div><section class="category-chart"><div class="chart-heading"><div><h3>错题类别</h3><p>按专题统计题目数量</p></div><span>${topicCounts.size} 个类别</span></div>${topics.length?`<div class="chart-rows">${topics.map(x=>`<div class="chart-row"><span class="chart-subject">${subject(x.subject).name}</span><span class="chart-topic" title="${esc(x.topic)}">${esc(x.topic)}</span><span class="chart-track"><i style="width:${Math.max(8,Math.round(x.count/maxTopic*100))}%"></i></span><b>${x.count}</b></div>`).join('')}</div>`:'<p class="chart-empty">录入题目后会显示类别统计</p>'}</section><div class="overview-grid">${subjects.map(s=>`<button data-subject="${s.id}" class="overview-card"><span>${icon(s.icon)} ${s.name}</span><strong>${state.questions.filter(q=>q.subject===s.id).length}</strong><small>查看题目 →</small></button>`).join('')}</div>`;$('question-list').innerHTML=!selectedSubject?'':items.length?pageItems.map(q=>{const s=subject(q.subject);return `<article class="question-card ${selectedIds.has(q.id)?'selected':''}"><div class="card-top"><label class="question-select"><input type="checkbox" data-select-id="${esc(q.id)}" aria-label="选择题目：${esc(q.topic)}" ${selectedIds.has(q.id)?'checked':''}><span>本次打印</span></label><div class="tags"><span class="tag subject" style="${style(s)}">${s.name}</span><span class="topic-tag" title="${esc(q.topic)}">${esc(q.topic)}</span></div><span class="card-status ${q.mastered?'mastered':''}">${q.mastered?'✓ 已掌握':'○ 待复习'}</span></div><div class="question-text">${richQuestion(q)}</div>${q.answer?`<div class="card-answer"><b>答案</b>${Formula.render(q.answer)}</div>`:''}<div class="card-bottom"><small>${q.demo?'示例题 · ':''}上传于 ${q.createdAt?new Date(q.createdAt).toLocaleDateString('zh-CN'):''}</small><div class="card-actions"><select class="mastery-select" data-mastery-id="${esc(q.id)}" aria-label="题目掌握状态：${esc(q.topic)}"><option value="review" ${q.mastered?'':'selected'}>待复习</option><option value="mastered" ${q.mastered?'selected':''}>已掌握</option></select><button data-action="edit" data-id="${esc(q.id)}">${icon('edit')}编辑</button><button data-action="delete" data-id="${esc(q.id)}" class="delete" aria-label="删除题目">${icon('trash')}</button></div></div></article>`;}).join(''):`<div class="empty-state">${icon('book')}<h3>还没有匹配的题目</h3><p>调整筛选条件后再试。</p></div>`;renderSelection();schedulePreview();}
  $('question-pagination').onclick=e=>{const button=e.target.closest('[data-page]');if(!button||button.disabled)return;currentPage=Number(button.dataset.page);renderList();};
  function animateBrand(){const mark=document.querySelector('.brand-mark');if(mark._waveTimer)clearTimeout(mark._waveTimer);mark.classList.remove('is-wave','is-bouncing');void mark.offsetWidth;mark.classList.add('is-wave');const reset=()=>{mark.classList.remove('is-wave','is-bouncing');mark._waveTimer=null;};if(matchMedia('(prefers-reduced-motion: reduce)').matches){mark._waveTimer=setTimeout(reset,420);return;}mark.classList.add('is-bouncing');let frames=0;const tick=()=>{if(frames>=6){reset();return;}mark.classList.toggle('is-wave');frames++;mark._waveTimer=setTimeout(tick,100);};mark._waveTimer=setTimeout(tick,100);}
  document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();animateBrand();});
  function renderAll(){selectedIds=new Set([...selectedIds].filter(id=>state.questions.some(q=>q.id===id)));renderNav();renderTopics();renderList();}
  function selectSubject(s,push=true){if(editing){toast('请先保存或取消当前编辑。');return;}if(selectedSubject!==s)selectedIds.clear();selectedSubject=s;currentPage=1;topicFilters.clear();topicsExpanded=false;if(push&&location.pathname!=='/'+(s||'overview'))history.pushState(null,'','/'+(s||'overview'));document.title=(s?subject(s).name+'错题':'错题本')+' · 比格多栋';renderAll();}
  document.addEventListener('click',async e=>{const s=e.target.closest('[data-subject]');if(s)selectSubject(s.dataset.subject);const a=e.target.closest('[data-action]');if(!a)return;const q=state.questions.find(q=>q.id===a.dataset.id);if(a.dataset.action==='add')openEditor();if(a.dataset.action==='edit'&&q)openEditor(q);if(a.dataset.action==='mastery'&&q){const updated={...state,questions:state.questions.map(x=>x.id===q.id?{...x,mastered:!x.mastered,updatedAt:new Date().toISOString()}:x)};if(await commit(updated)){renderAll();toast(q.mastered?'已标记为待复习':'已标记为已掌握');}}if(a.dataset.action==='delete'&&q)confirmDelete(q);});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-image]');if(!b)return;$('image-large').src=b.dataset.image;$('image-large').alt=b.dataset.alt;$('image-caption').textContent=b.dataset.alt;$('image-dialog').showModal();});$('image-close').onclick=()=>$('image-dialog').close();
  $('search-input').addEventListener('input',e=>{query=e.target.value;currentPage=1;renderList();});
  $('topic-options-filter').onchange=e=>{if(!e.target.matches('input[type=checkbox]'))return;e.target.checked?topicFilters.add(e.target.value):topicFilters.delete(e.target.value);currentPage=1;$('topic-summary').textContent=topicFilters.size?`已选 ${topicFilters.size} 类`:'全部类别';renderList();};$('topic-expand').onclick=()=>{topicsExpanded=!topicsExpanded;renderTopics();};
  $('status-filter').onchange=e=>{statusFilter=e.target.value;currentPage=1;renderList();};
  $('date-from').onchange=e=>{todayMode=false;$('today-filter').classList.remove('active');dateFrom=e.target.value;currentPage=1;renderList();};$('date-to').onchange=e=>{todayMode=false;$('today-filter').classList.remove('active');dateTo=e.target.value;currentPage=1;renderList();};
  $('today-filter').onclick=()=>{todayMode=true;const now=new Date();const start=new Date(now);if(now.getHours()<6)start.setDate(start.getDate()-1);dateFrom=localDate(start);dateTo=localDate(now);$('date-from').value=dateFrom;$('date-to').value=dateTo;$('today-filter').classList.add('active');renderList();};$('clear-dates').onclick=()=>{todayMode=false;$('today-filter').classList.remove('active');dateFrom=dateTo='';$('date-from').value=$('date-to').value='';renderList();};
  $('question-list').onchange=async e=>{const masteryId=e.target.dataset.masteryId;if(masteryId){const q=state.questions.find(q=>q.id===masteryId);if(!q)return;const mastered=e.target.value==='mastered';e.target.disabled=true;await commit({...state,questions:state.questions.map(x=>x.id===masteryId?{...x,mastered,updatedAt:new Date().toISOString()}:x)});renderAll();return;}const id=e.target.dataset.selectId;if(!id)return;e.target.checked?selectedIds.add(id):selectedIds.delete(id);e.target.closest('.question-card').classList.toggle('selected',e.target.checked);renderSelection();updatePreview();};
  $('select-visible').onclick=()=>{filtered().forEach(q=>selectedIds.add(q.id));renderList();};$('clear-selection').onclick=()=>{selectedIds.clear();renderList();};
  $('reset-filter').onclick=()=>{query='';topicFilters.clear();topicsExpanded=false;statusFilter='';dateFrom=dateTo='';todayMode=false;$('today-filter').classList.remove('active');$('search-input').value='';$('status-filter').value='';$('date-from').value=$('date-to').value='';renderAll();};
  function updateEditorTopics(){const s=subject($('f-subject').value);$('topic-options').innerHTML=[...new Set([...s.topics,...state.questions.filter(q=>q.subject===s.id).map(q=>q.topic)])].map(t=>`<option value="${esc(t)}"></option>`).join('');$('chemistry-panel').hidden=s.id!=='chemistry';}
  function draft(){return {id:editingId||'draft',subject:$('f-subject').value,topic:$('f-topic').value.trim()||'未命名专题',question:$('f-question').value,answer:$('f-answer').value,explanation:$('f-explanation').value,notes:$('f-notes').value,equation:$('f-subject').value==='chemistry'?$('f-equation').value:'',equationPlain:$('f-subject').value==='chemistry'?$('f-equationPlain').value:'',images:state.questions.find(q=>q.id===editingId)?.images||[],mastered:$('f-mastered').checked};}
  function openEditor(q=null,restored=false){if(!ready){toast('请先启动本地服务并等待题库连接。');return;}editing=true;document.body.classList.add('editing-mode');editingRevision=revision;editingId=q?.id||null;$('collection-panel').hidden=true;$('editor-panel').hidden=false;$('editor-heading').textContent=editingId?'编辑题目':'录入新题';$('form-message').textContent='';$('f-subject').value=q?.subject||selectedSubject||'chemistry';['topic','question','answer','explanation','notes','equation','equationPlain'].forEach(k=>$('f-'+k).value=q?.[k]||'');$('f-mastered').checked=!!q?.mastered;updateEditorTopics();checkChemistry();updatePreview();if(!restored)$('f-topic').focus();}
  function closeEditor(){editing=false;document.body.classList.remove('editing-mode');editingId=null;$('collection-panel').hidden=false;$('editor-panel').hidden=true;try{localStorage.removeItem(DRAFT);}catch(e){}renderAll();}
  function cancelEditor(){const d=draft();const original=state.questions.find(q=>q.id===editingId);const dirty=['subject','topic','question','answer','explanation','notes','equation','equationPlain','mastered'].some(k=>(d[k]||'')!==(original?.[k]||''));if(dirty&&['question','answer','explanation','notes','equation'].some(k=>d[k])){showConfirm('放弃本次编辑？','未保存的内容将被丢弃。','放弃编辑',closeEditor);}else closeEditor();}
  $('add-btn').onclick=()=>{if(editing){toast('正在编辑中，保存后可继续录入。');return;}openEditor();};$('back-btn').onclick=cancelEditor;$('cancel-btn').onclick=cancelEditor;
  $('question-form').addEventListener('input',()=>{updateEditorTopics();checkChemistry();try{localStorage.setItem(DRAFT,JSON.stringify({...draft(),id:editingId}));}catch(e){}schedulePreview();});
  $('question-form').onsubmit=async e=>{e.preventDefault();const q=draft();q.topic=$('f-topic').value.trim();q.question=q.question.trim();q.id=editingId||id();if(formulaProblems(q).length){$('form-message').textContent='公式语法未通过，请修正标红的公式后保存。';return;}if(!validQuestion(q)){$('form-message').textContent='请填写学科、专题和题目，并检查内容长度。';return;}const original=state.questions.find(x=>x.id===editingId);const record={...q,id:original?.id||q.id,createdAt:original?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),demo:false};const next={...state,questions:original?state.questions.map(x=>x.id===original.id?record:x):[record,...state.questions]};if(await commit(next,editingRevision)){closeEditor();toast('已写入本地题库，打印预览已同步。');}};
  function checkChemistry(){const q=draft();let raw=q.equationPlain||q.equation;const parts=Formula.tokenize(q.equation);if(!q.equationPlain&&parts.length===1&&parts[0].type==='math'&&parts[0].value.startsWith('\\ce{')&&parts[0].value.endsWith('}'))raw=parts[0].value.slice(4,-1).replace(/<=>/g,'⇌').replace(/->/g,'→').replace(/\s+v\s*/g,'↓');const result=[Chemistry.checkEquation(raw),...Chemistry.knowledgeHints([q.question,q.answer,q.explanation,q.notes,q.equation].join(' '))];$('chemistry-results').innerHTML=result.map(r=>`<div class="check-result ${r.level}">${icon(r.level==='good'?'check':r.level==='error'||r.level==='warning'?'warning':'info')}<div><b>${esc(r.title)}</b><br>${esc(r.detail)}</div></div>`).join('');const problems=formulaProblems(q);$('formula-check').classList.toggle('has-errors',!!problems.length);$('formula-check').textContent=problems.length?'公式待修正：'+problems.map(p=>p.field+'：'+p.error).join('；'):'公式语法检查通过 · KaTeX + mhchem（不代表推导或反应结论已验证）';$('save-question-btn').disabled=!!problems.length;}
  let confirmAction=null;function showConfirm(title,message,label,action){$('confirm-title').textContent=title;$('confirm-message').textContent=message;$('confirm-ok').textContent=label;confirmAction=action;$('confirm-dialog').showModal();}$('confirm-cancel').onclick=()=>$('confirm-dialog').close();$('confirm-ok').onclick=()=>{$('confirm-dialog').close();confirmAction?.();};
  function confirmDelete(q){showConfirm('删除这道题？','删除前会保留一份本地历史快照，可从 data/history 恢复。','删除题目',async()=>{if(await commit({...state,questions:state.questions.filter(x=>x.id!==q.id)})){renderAll();toast('题目已删除');}});}
  async function setSetting(k,v){const before=revision;const next={...state,settings:{...state.settings,[k]:v}};if(await commit(next)){if(editing&&editingRevision===before)editingRevision=revision;syncSettings();updatePreview();}else syncSettings();}
  function syncSettings(){const s=state.settings;$('paper-size').value=s.paper;$('compact-mode').checked=s.compact;$('show-answers').checked=s.answers;for(const[n,v]of[['single-column',1],['double-column',2]]){$(n).classList.toggle('active',s.columns===v);$(n).setAttribute('aria-pressed',s.columns===v?'true':'false');}}
  $('paper-size').onchange=e=>setSetting('paper',e.target.value);$('single-column').onclick=()=>setSetting('columns',1);$('double-column').onclick=()=>setSetting('columns',2);$('compact-mode').onchange=e=>setSetting('compact',e.target.checked);$('show-answers').onchange=e=>setSetting('answers',e.target.checked);
  function schedulePreview(){clearTimeout(previewTimer);previewTimer=setTimeout(()=>{updatePreview();},170);}
  function titleFor(items){if(editing)return subject(draft().subject).name+' · '+draft().topic;return (selectedSubject?subject(selectedSubject).name:'我的')+'错题专题集'+(topicFilters.size===1?' · '+[...topicFilters][0]:'');}
  async function updatePreview(){clearTimeout(previewTimer);try{await Printer.render(editing?[draft()]:selectedSubject?selectedQuestions():[],state.settings,titleFor(),Object.fromEntries(subjects.map(s=>[s.id,s.name])));}catch(e){$('preview-meta').textContent='预览失败：'+e.message;$('print-btn').disabled=true;}}
  $('prev-page').onclick=()=>Printer.previous();$('next-page').onclick=()=>Printer.next();window.addEventListener('resize',Printer.scale);window.addEventListener('resize',()=>{if(selectedSubject)renderTopics();});$('print-btn').onclick=async()=>{await updatePreview();if(!$('print-btn').disabled)window.print();};
  let activeField=null;document.addEventListener('focusin',e=>{if(e.target.matches('#question-form textarea,#f-equation'))activeField=e.target;});document.querySelectorAll('[data-insert]').forEach(b=>b.onclick=()=>{if(!activeField)activeField=$('f-question');const snippets={fraction:'\\(\\frac{a}{b}\\)',power:'\\(a_n^2\\)',chem:'\\(\\ce{H2O}\\)'};const start=activeField.selectionStart,end=activeField.selectionEnd;activeField.setRangeText(snippets[b.dataset.insert],start,end,'end');activeField.focus();activeField.dispatchEvent(new Event('input',{bubbles:true}));});
  function subjectFromPath(){const name=location.pathname.slice(1);return subjects.some(s=>s.id===name)?name:'';}
  selectedSubject=subjectFromPath();
  if(location.pathname==='/'||location.pathname==='/index.html')history.replaceState(null,'','/overview');
  document.title=(selectedSubject?subject(selectedSubject).name+'错题':'错题本')+' · 比格多栋';
  window.addEventListener('popstate',()=>{if(editing){try{localStorage.setItem(DRAFT,JSON.stringify({...draft(),id:editingId}));}catch(e){}editing=false;editingId=null;document.body.classList.remove('editing-mode');$('editor-panel').hidden=true;$('collection-panel').hidden=false;}selectSubject(subjectFromPath(),false);});
  $('f-subject').innerHTML=subjects.map(s=>`<option value="${s.id}">${s.name}</option>`).join('');icons();syncSettings();renderAll();
  loadLocal().then(()=>{try{const saved=JSON.parse(localStorage.getItem(DRAFT)||'null');if(saved&&typeof saved.question==='string'&&NoteSchema.subjects.includes(saved.subject)){if(saved.id&&!state.questions.some(q=>q.id===saved.id))saved.id=null;openEditor(saved,true);toast('已恢复上次未保存的草稿。');}}catch(e){}});setInterval(()=>loadLocal(),2000);document.fonts.ready.then(schedulePreview);document.fonts.addEventListener('loadingdone',schedulePreview);
})();
